import sys
import os
import json
import urllib.request
import subprocess
import http.server
from http.server import BaseHTTPRequestHandler, HTTPServer
import threading
import base64
import re
import time

HTML_B64 = ''

SYSINFO_PS = '\n            $os = Get-CimInstance Win32_OperatingSystem\n            $cpu = Get-CimInstance Win32_Processor\n            $mem = $os.FreePhysicalMemory / 1024 / 1024\n            $tot = $os.TotalVisibleMemorySize / 1024 / 1024\n            $vol = Get-CimInstance Win32_Volume | Where-Object { $_.DriveLetter -eq \'C:\' }\n            $disk = $vol.FreeSpace / 1024 / 1024 / 1024\n            $totDisk = $vol.Capacity / 1024 / 1024 / 1024\n            @{\n                cpu = $cpu.LoadPercentage\n                ram = "{0:N1} GB free of {1:N1} GB" -f $mem, $tot\n                disk = "{0:N1} GB free of {1:N1} GB" -f $disk, $totDisk\n                uptime = (New-TimeSpan -Start $os.LastBootUpTime -End (Get-Date)).ToString("d\'d \'h\'h \'m\'m\'")\n            } | ConvertTo-Json\n            '
PROCESSES_PS = '\n            Get-Process | Sort-Object CPU -Descending | Select-Object -First 10 Id, ProcessName, CPU, WS | ConvertTo-Json\n            '
SYS_INSTRUCTION = "\n\nCRITICAL INSTRUCTION: You are a system assistant. If the user asks you to perform ANY action, open an app, or run a command, you MUST output the exact PowerShell command inside a ```powershell-system block. DO NOT use standard markdown code blocks. Example:\n```powershell-system\nStart-Process notepad\n```\nNEVER ask the user to run it themselves. YOU must run it by using the powershell-system block. Explain what you did briefly but DO NOT say 'Here is the command for you to run' because the system runs it automatically."

def run_ps1(cmd):
    result = subprocess.run(
        ['powershell', '-ExecutionPolicy', 'Bypass', '-Command', cmd],
        stdout=subprocess.PIPE,
        stderr=subprocess.PIPE,
        creationflags=subprocess.CREATE_NO_WINDOW
    )
    stdout = result.stdout.decode('utf-8', errors='ignore')
    stderr = result.stderr.decode('utf-8', errors='ignore')
    rc = result.returncode
    return stdout, stderr, rc


class JarvisHandler(BaseHTTPRequestHandler):
    def log_message(self, format, *args):
        pass  # Suppress console logging

    def do_GET(self):
        if self.path == '/' or self.path == '/index.html':
            self.send_response(200)
            self.send_header('Content-Type', 'text/html')
            self.end_headers()
            self.wfile.write(base64.b64decode(HTML_B64))
            return

        if self.path.startswith('/api/sysinfo'):
            stdout, stderr, rc = run_ps1(SYSINFO_PS)
            self.send_response(200)
            self.send_header('Content-Type', 'application/json')
            self.end_headers()
            self.wfile.write(stdout.encode('utf-8'))
            return

        if self.path.startswith('/api/processes'):
            stdout, stderr, rc = run_ps1(PROCESSES_PS)
            self.send_response(200)
            self.send_header('Content-Type', 'application/json')
            self.end_headers()
            self.wfile.write(stdout.encode('utf-8'))
            return

        if self.path.startswith('/api/config'):
            self.send_response(200)
            self.send_header('Content-Type', 'application/json')
            self.end_headers()
            self.wfile.write(json.dumps({'apiKey': '', 'ollama_local_mode': True}).encode('utf-8'))
            return

        self.send_response(404)
        self.end_headers()

    def do_OPTIONS(self):
        self.send_response(200)
        self.send_header('Access-Control-Allow-Origin', '*')
        self.send_header('Access-Control-Allow-Methods', 'GET, POST, OPTIONS')
        self.send_header('Access-Control-Allow-Headers', 'Content-Type')
        self.end_headers()

    def do_POST(self):
        length = int(self.headers.get('Content-Length', 0))
        body = self.rfile.read(length).decode('utf-8') if length > 0 else '{}'
        try:
            data = json.loads(body)
        except Exception:
            data = {}

        if self.path.startswith('/api/chat'):
            messages = data.get('contents', [])
            api_key = data.get('apiKey', '')
            ollama_local_mode = data.get('ollama_local_mode', True)

            ollama_messages = []
            for item in messages:
                role = item.get('role', 'user')
                if role == 'model':
                    role = 'assistant'
                text = ''
                for part in item.get('parts', []):
                    text += part.get('text', '')
                ollama_messages.append({'role': role, 'content': text})

            reply = ''
            try:
                req_data = json.dumps({
                    'model': 'llama3.2',
                    'messages': ollama_messages,
                    'stream': False,
                    'options': {
                        'num_gpu': -1,
                        'use_mmap': True,
                        'num_ctx': 4096
                    }
                }).encode('utf-8')
                req = urllib.request.Request(
                    'http://localhost:11434/api/chat',
                    data=req_data,
                    headers={'Content-Type': 'application/json'}
                )
                response = urllib.request.urlopen(req)
                ollama_res = json.loads(response.read().decode('utf-8'))
                reply = ollama_res['message']['content']

                if '```powershell-system' in reply:
                    parts_split = reply.split('```powershell-system\n')
                    if len(parts_split) > 1:
                        cmd_part = parts_split[1].split('```\n')[0]
                        run_ps1(cmd_part)

            except Exception as e:
                reply = '[SYSTEM ERROR] Could not connect to local Ollama instance: ' + str(e)

            self.send_response(200)
            self.send_header('Content-Type', 'application/json')
            self.send_header('Access-Control-Allow-Origin', '*')
            self.end_headers()
            self.wfile.write(json.dumps({'candidates': [{'content': {'parts': [{'text': reply}]}}]}).encode('utf-8'))
            return

        if self.path.startswith('/api/cmd') or self.path.startswith('/api/exec'):
            cmd = data.get('command', '')
            stdout, stderr, rc = run_ps1(cmd)
            self.send_response(200)
            self.send_header('Content-Type', 'application/json')
            self.send_header('Access-Control-Allow-Origin', '*')
            self.end_headers()
            self.wfile.write(json.dumps({'status': rc, 'stdout': stdout, 'stderr': stderr}).encode('utf-8'))
            return

        if self.path.startswith('/api/kill'):
            pid = data.get('pid', '')
            run_ps1('Stop-Process -Id ' + str(pid) + ' -Force')
            self.send_response(200)
            self.send_header('Content-Type', 'application/json')
            self.send_header('Access-Control-Allow-Origin', '*')
            self.end_headers()
            self.wfile.write(json.dumps({'status': 'Killed'}).encode('utf-8'))
            return

        if self.path.startswith('/api/shutdown'):
            self.send_response(200)
            self.send_header('Content-Type', 'application/json')
            self.send_header('Access-Control-Allow-Origin', '*')
            self.end_headers()
            self.wfile.write(json.dumps({'status': 'ok'}).encode('utf-8'))
            def killer():
                os._exit(0)
            t = threading.Thread(target=killer)
            t.start()
            return

        self.send_response(404)
        self.end_headers()


def run_server():
    os.environ['CUDA_VISIBLE_DEVICES'] = '0'
    os.environ['OLLAMA_CUDA_VISIBLE_DEVICES'] = '0'
    server = HTTPServer(('', 9000), JarvisHandler)
    server.serve_forever()


if __name__ == '__main__':
    import webview

    # Start the HTTP server in a background thread
    t = threading.Thread(target=run_server, daemon=True)
    t.start()

    # Give the server a moment to start
    time.sleep(0.8)

    # Open a native system window instead of a browser tab
    window = webview.create_window(
        'JARVIS - System Console',
        'http://localhost:9000',
        width=1400,
        height=900,
        resizable=True,
        min_size=(900, 600),
        background_color='#040814'
    )
    webview.start()
